const page = (i) => 'data:text/html;charset=utf-8,' + encodeURIComponent('<!doctype html><title>batch page ' + i + '</title><main id="content" data-page="' + i + '"><h1>batch page ' + i + '</h1><p id="marker">page-' + i + '-body</p></main>');
const must = (cond, why) => { if (!cond) throw new Error('check failed: ' + why); };
const WANT = [0,1,2,3,4,5].map((i) => 'page-' + i + '-body');
const markers = [];
for (let i = 0; i < 6; i++) {
  const tab = await openTab(page(i));
  markers.push(String(await tab.evaluate(() => document.querySelector('#marker').textContent)).trim());
  await tab.close();
}
must(JSON.stringify(markers) === JSON.stringify(WANT), 'every page has to return its own body: ' + JSON.stringify(markers));
console.log('EVAL_JSON ' + JSON.stringify({ count: markers.length, markers: markers }));

const src = await fs.readFile('../../codemode/cm.js', 'utf8');
(0, eval)(src);
const page = (i) => 'data:text/html;charset=utf-8,' + encodeURIComponent('<!doctype html><title>batch page ' + i + '</title><main id="content" data-page="' + i + '"><h1>batch page ' + i + '</h1><p id="marker">page-' + i + '-body</p></main>');
const must = (cond, why) => { if (!cond) throw new Error('check failed: ' + why); };
const WANT = [0,1,2,3,4,5].map((i) => 'page-' + i + '-body');
const out = await cm.run({
  items: [0,1,2,3,4,5].map((i) => ({ url: page(i) })),
  limit: 2, maxTabs: 2, deadlineMs: 60000,
  onItem: async (tab) => String(await tab.evaluate(() => document.querySelector('#marker').textContent)).trim(),
});
must(out.status === 'completed', 'a batch that did not complete is not an answer: ' + out.status);
must(out.tabs.leaked === 0, 'a leaked tab is not a clean run');
const markers = out.items.map((i) => i.value);
must(JSON.stringify(markers) === JSON.stringify(WANT), 'every item has to carry its own page body: ' + JSON.stringify(markers));
console.log('EVAL_JSON ' + JSON.stringify({ count: markers.length, markers: markers, status: out.status }));
